def longestSubsequence(nums):
        slow=0
        i=0
        xor=0
        maxlength=0
        while i<len(nums):
            xor^=nums[i]
            while xor==0 and i!=0 and slow<=i:
                if (i<len(nums)-1) and (nums[i+1]^xor!=0):
                    break
                xor^=nums[slow]
                slow+=1
            i+=1
            maxlength=max(maxlength,i-slow)
        return maxlength

